using OpenSpace;
var root = Path.Combine(Path.GetTempPath(), "openspace-" + Guid.NewGuid().ToString("N")); Directory.CreateDirectory(Path.Combine(root, "nested")); File.WriteAllText(Path.Combine(root, "small.txt"), "small"); File.WriteAllBytes(Path.Combine(root, "nested", "large.bin"), new byte[4096]); var results = ScanEngine.Scan(root); if (!results.Any(x => x.Path.EndsWith("large.bin") && x.Bytes == 4096) || results.First().Bytes < 4096) throw new Exception("Scan did not rank file sizes correctly."); using var cts = new CancellationTokenSource(); cts.Cancel(); try { ScanEngine.Scan(root, cts.Token); throw new Exception("Cancellation was ignored."); } catch (OperationCanceledException) { } Directory.Delete(root, true); Console.WriteLine("PASS: read-only scan, ranking, and cancellation");
